        "en": "I usually have the bills automatically deducted from my account. If my account is empty, I will wire transfer the money. Contracts must be taken seriously and are very important in England! If you breach a contract in this country you will certainly get into trouble. If your income is fluctuating it is probably best to avoid contracts.",
