        "id": "p1",
        "en": "I was born in Dayton, Ohio, but to tell the truth, I never felt very comfortable there. Fortunately, I discovered different countries when I was still a teenager. My parents traveled a lot and we were lucky to be able to live in different countries. For I can remember Asia, especially Japan, has always fascinated me. Europe is interesting, but most countries are not easy to live in, although the culture and especially the food was always the best.",
        "th": "ฉันเกิดที่เมืองเดย์ตัน รัฐโอไฮโอ แต่บอกตามตรงว่าฉันไม่เคยรู้สึกสบายใจที่นั่นเลย โชคดีที่ฉันค้นพบประเทศต่างๆ เมื่อยังเป็นวัยรุ่น พ่อแม่ของฉันเดินทางบ่อยมาก และเราโชคดีที่ได้อยู่ต่างประเทศ เพราะฉันจำได้ว่าเอเชียโดยเฉพาะญี่ปุ่นทำให้ฉันหลงใหลมาโดยตลอด ยุโรปเป็นประเทศที่น่าสนใจ แต่ประเทศส่วนใหญ่อยู่ได้ไม่ง่ายนัก แม้ว่าวัฒนธรรมและโดยเฉพาะอาหารจะดีที่สุดก็ตาม"
