        "th": "เมื่อฉันโตขึ้นฉันก็เริ่มท่องเที่ยวด้วยตัวเอง ฉันขับรถไปเม็กซิโกและเดินทางไปจนถึงปานามา แน่นอนว่าสิ่งเหล่านี้เป็นการผจญภัยมากกว่าการเดินทางทั่วไป ฉันบอกได้เลยว่าการเดินทางให้ความรู้ในหลายๆ ด้าน คุณยังได้เรียนรู้วัฒนธรรมที่แตกต่างกัน และฉันก็พัฒนาทักษะทางสังคมได้ค่อนข้างดี คนอเมริกันส่วนใหญ่เดินทางภายในประเทศของตนเองเท่านั้น และก็ไม่มีอะไรผิดปกติ แต่ฉันรู้สึกว่าประสบการณ์ในต่างประเทศให้ความรู้มากขึ้นและดีต่อสมอง"
