        "id": "p2",
        "en": "Everything seems to be black! The man tells me the phone was damaged by a short circuit. The repair would cost two hundred dollar. He also says that the phone has become wet, and that's how it broke. Today he has an offer for a new phone. The new phone costs only three hundred dollar. I have no choice but to buy a new phone. I'm never going to use my phone in the bathtub again.",
        "th": "ทุกอย่างดูเหมือนจะเป็นสีดำ! ชายคนนั้นบอกฉันว่าโทรศัพท์ได้รับความเสียหายจากการลัดวงจร การซ่อมแซมจะมีค่าใช้จ่ายสองร้อยดอลลาร์ เขายังบอกด้วยว่าโทรศัพท์เปียก และมันก็พัง วันนี้เขามีข้อเสนอสำหรับโทรศัพท์ใหม่ โทรศัพท์รุ่นใหม่มีราคาเพียงสามร้อยดอลลาร์ ฉันไม่มีทางเลือกนอกจากซื้อโทรศัพท์ใหม่ ฉันจะไม่มีวันใช้โทรศัพท์ในอ่างอาบน้ำอีกต่อไป"
