        "id": "p1",
        "en": "My family loves to buy fresh products from local farms; that's why we all go on Saturdays to the farmer's market. My husband is a hobby chef, and he only buys vegetables at the market. Our favorite stand is at the end of the market where we can also buy fresh herbs. \"Good morning Lisa and Harry, so nice to see you again.\" \"Good morning Bill! What is the freshest thing you have today?\" \"Harry, you know that all my products are fresh, everything has just arrived directly from the eco-farm.\" \"So, from all the tables and stalls here, you deliver them here first?\" \"That's right. I am here at the entrance of the market that's why my tables come first.\" \"Okay Bill, then we will have two pounds of tomatoes, and about three pounds of potatoes. And also a bundle of carrots please.\" \"Anything else?\" \" Do you also sell figs?\" \"No, they don't grow around here.\" \"Ok, how much do I owe you?\"",
