        "en": "Last week, my grandma died. The whole family is very sad. The funeral will take place in the late afternoon, and perhaps some of the family will join together for a dinner at a restaurant. By tradition, most of the dead are buried but cremations are becoming more common, as some people think it's more practical. When people go to a funeral they meet in the church first.",
