    "summary": "ในช่วงหลายปีที่ผ่านมา การสมัครสมาชิกเคเบิลทีวีของเรากลายเป็นภาระมากกว่าความบันเทิง เราไม่ได้รวยและต้องนับเงินทุกบาททุกสต...",
