        "th": "อย่างไรก็ตาม เมื่อเราเริ่ม เราจะทำความสะอาดห้องของเด็กๆ ก่อน เราทำความสะอาดพื้นและเช็ดหน้าต่าง เราต้องถูพื้นซ้ำหลายครั้งจนเงางามเหมือนใหม่ ฉันทำความสะอาดเฟอร์นิเจอร์ และโดยปกติฉันใช้เวลาประมาณครึ่งวันในการทำความสะอาดห้องครัว พี่ชายของฉันทำความสะอาดโรงรถและช่วยนำขยะออกไป เราเป็นครอบครัวที่สะอาดและทำงานได้ดี พร้อมด้วยบ้านที่สะอาดและเด็กๆ ที่มีสุขภาพดี เราภูมิใจในตัวเองอย่างถูกต้อง"
