        "id": "p1",
        "en": "Elsa seriously thought she was pregnant. Her stomach already looked like she had swallowed a few basketballs when she decided it was time to call her doctor to hear the results from the last exams. But just like last time, the doctor confirmed that she wasn't pregnant at all. Still, over the next few weeks, Elsa gained more pounds. In addition, the shape of her stomach had become strange; it looked like a huge potato. The scale showed over 300 pounds and Elsa just couldn't find an explanation.",
        "th": "เอลซ่าคิดอย่างจริงจังว่าเธอท้อง ท้องของเธอดูเหมือนกลืนลูกบาสเก็ตบอลไปสองสามลูกแล้ว เมื่อเธอตัดสินใจว่าถึงเวลาต้องโทรหาแพทย์เพื่อฟังผลการสอบครั้งล่าสุด แต่เหมือนครั้งที่แล้ว หมอยืนยันว่าไม่ได้ท้องเลย อย่างไรก็ตาม ในอีกไม่กี่สัปดาห์ข้างหน้า Elsa ก็มีน้ำหนักเพิ่มขึ้น นอกจากนี้ รูปร่างท้องของเธอก็แปลก มันดูเหมือนมันฝรั่งขนาดใหญ่ เครื่องชั่งแสดงน้ำหนักได้มากกว่า 300 ปอนด์ และเอลซ่าก็หาคำอธิบายไม่ได้"
