        "id": "p2",
        "en": "One of his colleagues has always been suspicious and envious of him. After some research on the internet, he finds out that Mr. Meyer's fiance has a questionable past. He reports his findings to the directors. They give Mr. Meyer a choice. He can keep his job but he must not marry that woman, or he must leave the company. Mr. Meyer is desperate. Should he marry the woman or keep his job? Eventually, Mr. Meyer tells his bosses. \"I will marry.",
