        "th": "ทุกๆ วันเธอจะค้นหาข้อมูลจากเว็บไซต์รับสมัครงานและหนังสือพิมพ์ท้องถิ่นเพื่อหาตำแหน่งงานว่าง เธอส่งเรซูเม่ของเธอไปยังทุกบริษัทที่เธอนึกถึงด้วยความหวังว่าจะได้งานทำ เนื่องจากการว่างงานทำให้เงินออมของเธอลดลง หลักการสำคัญที่สุดประการหนึ่งของเธอคือการไม่ยอมแพ้ งานในฝันของเธอยังคงเป็นนักบัญชี แต่เธอรู้ดีว่ายุคสมัยเปลี่ยนไป เธอมีความยืดหยุ่น เนื่องจากการหางานเป็นเลขานุการก็จะเป็นประโยชน์ต่อเธอเช่นกัน"
