        "th": "มาเรียลองไปร้านอาหารและพบว่าอาหารอร่อย อาหารเกือบทั้งหมดเป็นอาหารมังสวิรัติ และบางจานก็เป็นอาหารมังสวิรัติเท่านั้นด้วยซ้ำ หลังจากนั้นไม่นาน มาเรียก็กลายเป็นลูกค้าประจำ อาหารโปรดของเธอคือซุปผักที่ไม่ควรมีเนื้อสัตว์เลย วันหนึ่งเธอถามแม่ครัวว่าทำไมซุปถึงอร่อยเสมอไป เพราะเธออยากรู้เคล็ดลับ แม่ครัวตอบว่าเขาใช้น้ำสต๊อกไก่เป็นประจำ"
