        "id": "p1",
        "en": "We are retirees and live in a nursing home. Last fall we had a big storm. The storm was only the beginning. After it poured for days, the whole town became flooded. In the end, we had a power outage. The heating, electricity, and even the telephone was dead. At first, we took it lightly, but at night it got really cold with the temperature dropping below zero.",
        "th": "เราเกษียณแล้วและอาศัยอยู่ในบ้านพักคนชรา ฤดูใบไม้ร่วงที่แล้วเรามีพายุลูกใหญ่ พายุเป็นเพียงจุดเริ่มต้นเท่านั้น หลังจากฝนตกลงมาหลายวัน น้ำก็ท่วมทั้งเมือง ในที่สุดไฟฟ้าก็ดับ เครื่องทำความร้อน ไฟฟ้า และแม้แต่โทรศัพท์ก็ดับ ตอนแรกเราก็รับไปเบาๆ แต่กลางคืนก็หนาวมาก อุณหภูมิลดลงต่ำกว่าศูนย์"
