        "en": "I used to work on a construction site and I would call myself a construction worker. In those days I had to carry a lot of heavy material, often bricks and cement. At times, I also had to clean asphalt manually with a broom. One day, a little girl approached me and asked me why I sweated so much. “ But she continued by asking me, why don't I do anything else. \" Suddenly my boss came and yelled at me.",
