        "id": "p1",
        "en": "My name is Nicole. The most important aspect of life to me is looking and feeling healthy. Being beautiful is also a part of my business. A few years ago, I started an online business where I sell cosmetics and perfume. To expand my business, I use different social media platforms to spread the message such as Twitter and Facebook.",
        "th": "ฉันชื่อนิโคล สิ่งที่สำคัญที่สุดของชีวิตสำหรับฉันคือการดูดีและรู้สึกมีสุขภาพที่ดี ความสวยงามก็เป็นส่วนหนึ่งของธุรกิจของฉันเช่นกัน เมื่อไม่กี่ปีก่อน ฉันเริ่มธุรกิจออนไลน์โดยขายเครื่องสำอางและน้ำหอม เพื่อขยายธุรกิจของฉัน ฉันใช้แพลตฟอร์มโซเชียลมีเดียต่างๆ เพื่อเผยแพร่ข้อความ เช่น Twitter และ Facebook"
