        "th": "ฉันชื่อโซเฟีย ฉันอาศัยอยู่ที่เท็กซัสมาประมาณสามปีแล้ว ฉันมาที่นี่จากฮอนดูรัสพร้อมทั้งครอบครัว พี่เขยของฉันอาศัยอยู่ในสหรัฐอเมริกาเป็นเวลาหลายปีและเป็นพนักงานของรัฐ นั่นเป็นเหตุผลว่าทำไมครอบครัวที่เหลือจึงสามารถอพยพไปยังสหรัฐอเมริกาได้ มีความรุนแรงในประเทศบ้านเกิดของฉัน แต่เหตุผลที่เราต้องการตั้งถิ่นฐานในอเมริกาเหนือก็คือว่าค่าจ้างสูงกว่ามากและชีวิตโดยทั่วไปก็สะดวกสบายกว่า"
