        "th": "เราเพิ่งมาถึงโรงแรมของเรา ปีนี้เราจะไปพักผ่อนที่สเปน เราได้จองโรงแรมแบบรวมทุกอย่างไว้และการเช็คอินก็มีประสิทธิภาพมาก พนักงานต้อนรับที่เป็นมิตรให้กุญแจห้องแก่เราหลังจากที่เราจ่ายเงินประกันแล้ว เรามาจากประเทศอังกฤษ ตอนแรกดูเหมือนโรงแรมมีมาตรฐานที่สูงมาก ห้องพักกว้างขวางและทุกอย่างดูดี วันรุ่งขึ้นสิ่งต่าง ๆ ก็เริ่มแตกต่างออกไป"
