        "en": "Steve Jones is a taxi driver. He is a very hard working man. He drives his taxi for at least twelve hours a day. Sunday is the only day when he doesn't work. Although his job is very demanding, he meets a lot of different people. Many customers like to chat with Steve. Besides, he is driving a large limousine, and that makes the job more bearable.",
