        "en": "My work shift starts in fifteen minutes. Before I get to my workplace, I like to stop at a local bakery to buy a sandwich. As I open the door, there is already a long line of customers. There are at least eight people in front of me. They buy everything from cakes to fresh french bread. I have to be in the office in less than ten minutes. Then comes my turn.",
