        "id": "p2",
        "en": "As a matter of fact, Mr. Meyer has paid money for her time. One day, Mr. Meyer tells his colleague that he’s going to get married soon. But this colleague who has observed Mr. Meyer and thinks he knows something, tells the boss that Mr. Meyer plans to marry a woman of questionable reputation. The boss tells Mr. Meyer that he is no longer allowed to work for the company when he marries this woman. Mr. Meyer thinks carefully about his options. Should he marry the woman or keep the job? Finally, he tells his boss, \"I am going to get married, but not to this woman, instead I will marry my office.",
        "th": "ตามความเป็นจริง คุณเมเยอร์ได้จ่ายเงินเพื่อเวลาของเธอแล้ว วันหนึ่ง มิสเตอร์เมเยอร์บอกเพื่อนร่วมงานว่าเขากำลังจะแต่งงานเร็วๆ นี้ แต่เพื่อนร่วมงานคนนี้ที่สังเกตเห็นมิสเตอร์เมเยอร์และคิดว่าเขารู้อะไรบางอย่าง จึงบอกเจ้านายว่ามิสเตอร์เมเยอร์วางแผนที่จะแต่งงานกับผู้หญิงที่มีชื่อเสียงน่าสงสัย เจ้านายบอกมิสเตอร์เมเยอร์ว่าเขาไม่ได้รับอนุญาตให้ทำงานให้กับบริษัทอีกต่อไปเมื่อเขาแต่งงานกับผู้หญิงคนนี้ มิสเตอร์เมเยอร์คิดอย่างรอบคอบเกี่ยวกับทางเลือกต่างๆ ของเขา เขาควรแต่งงานกับผู้หญิงคนนั้นหรือเก็บงานไว้? ในที่สุด เขาบอกกับเจ้านายว่า \"ฉันกำลังจะแต่งงาน แต่ไม่ใช่กับผู้หญิงคนนี้ แต่ฉันจะแต่งงานกับที่ทำงานของฉันแทน\""
