        "th": "คุณโลแกนกำลังตัดสินใจครั้งสำคัญในชีวิต เขาตัดสินใจลาออกจากบริษัทและเริ่มต้นธุรกิจของตัวเอง เขาต้องการขายผลิตภัณฑ์จากบริษัทต่างๆ และใช้ข้อมูลติดต่อเดิมในการเริ่มต้น น่าเสียดายที่สิ่งต่างๆ ไม่เป็นไปตามที่คาดไว้ ลูกค้าเก่าของเขาไม่ยอมรับผลิตภัณฑ์ใหม่ของเขา แต่พวกเขาต้องการทำธุรกิจกับบริษัทเก่าของเขาต่อไป โชคดีที่คุณโลแกนเก็บเงินได้มากพอที่จะเกษียณอย่างสบายใจ"
