        "id": "p2",
        "en": "Marco explains that this is a very special knife from the traditional Spanish brand Muele. A knife for collectors! The beautiful evening has come to an end. As Marco is about to leave, Paula gives him a kiss and says that she wants to talk to him the next day. On Sunday Marco and Paula meet again. She feels very grateful for the splendid barbecue evening. They have a conversation and Marco tells her, that during their relationship not everything has been bad. Paula proposes to Marco; for the children, they could live together again. Indeed, after one week the family moves together again. Marco is very happy, especially because the cheap knife which he bought on his single vacation in Thailand didn’t fail to make an impression.",
        "th": "Marco อธิบายว่านี่เป็นมีดพิเศษจาก Muele แบรนด์สเปนดั้งเดิม มีดสำหรับนักสะสม! ค่ำคืนที่สวยงามได้สิ้นสุดลงแล้ว ขณะที่มาร์โกกำลังจะจากไป พอลล่าจูบเขาแล้วบอกว่าเธออยากคุยกับเขาในวันรุ่งขึ้น ในวันอาทิตย์ มาร์โกและพอลล่าพบกันอีกครั้ง เธอรู้สึกขอบคุณมากสำหรับค่ำคืนบาร์บีคิวอันแสนวิเศษ พวกเขามีการสนทนาและมาร์โกบอกเธอว่าในระหว่างความสัมพันธ์ของพวกเขาไม่ใช่ทุกสิ่งที่ไม่ดี พอลล่าขอมาร์โกแต่งงาน เพื่อลูกจะได้อยู่ร่วมกันได้อีกครั้ง หลังจากผ่านไปหนึ่งสัปดาห์ ครอบครัวก็ย้ายมาอยู่ด้วยกันอีกครั้ง มาร์โกมีความสุขมาก โดยเฉพาะอย่างยิ่งเพราะมีดราคาถูกที่เขาซื้อในช่วงวันหยุดเที่ยวเดียวที่ประเทศไทยไม่ได้สร้างความประทับใจเลย"
