        "id": "p1",
        "en": "Maria comes from Poland and works twice a week as a maid in a big house. The house belongs to Ms. Sanchez who is living alone. Once in a while, her son comes for a visit. Her son is unemployed and receives some money from his mother. The son lives at a friends' place. He often comes in the morning hours to his mother's house and is watching TV. If the weather is fine he sits on the terrace and drinks beer. Maria has to carry the empty beer bottles into the basement. In the basement are huge numbers of cases with full beer bottles stored. Ms. Sanchez works very hard.",
