        "en": "In former times Werner Schultz was an actor in a theater. In Berlin he was well known, and also had managed to get an important role for a television series in which he acted as a credible criminal. Mr. Schultz apparently was never poor and had always been interested in art and antiques. Now he was over fifty years old and received fewer offers from movies and theaters. But Mr. Schultz had also become quite famous as an art painter. It can be said that Mr. Schultz was a real artist and also a connoisseur of art, because he had wide knowledge, especially of antique paintings. He was well acquainted with the Impressionists of the 19th century. After many years as an artist, actor, and painting expert, Mr. Schultz was a welcomed customer in many shops and galleries. Mr. Schultz bought many valuable oil paintings and antiques in antique shops and art galleries. But his reputation for being a good supplier was even greater. The quality of his paintings and the merchandise he offered to sell were outstanding. One day newspapers reported that the famous art dealer and actor Werner Schultz had died. No one knew that he had died since Mr. Schultz had no relatives, therefore journalists were looking for friends and relatives.",
        "th": "ในสมัยก่อน แวร์เนอร์ ชูลทซ์เป็นนักแสดงในโรงละคร ในกรุงเบอร์ลินเขาเป็นที่รู้จักกันดีและยังสามารถได้รับบทบาทสำคัญในละครโทรทัศน์ที่เขาแสดงเป็นอาชญากรที่น่าเชื่อถือ เห็นได้ชัดว่านายชูลทซ์ไม่เคยยากจนและสนใจงานศิลปะและโบราณวัตถุมาโดยตลอด ตอนนี้เขาอายุเกินห้าสิบปีแล้วและได้รับข้อเสนอจากภาพยนตร์และโรงภาพยนตร์น้อยลง แต่มิสเตอร์ชูลทซ์ก็มีชื่อเสียงในฐานะจิตรกรด้วยเช่นกัน อาจกล่าวได้ว่ามิสเตอร์ชูลทซ์เป็นศิลปินตัวจริงและเป็นนักเลงศิลปะด้วย เพราะเขามีความรู้กว้างขวาง โดยเฉพาะภาพวาดโบราณ เขาคุ้นเคยกับอิมเพรสชั่นนิสต์แห่งศตวรรษที่ 19 เป็นอย่างดี หลังจากเป็นศิลปิน นักแสดง และผู้เชี่ยวชาญด้านการวาดภาพมาหลายปี คุณชูลทซ์ก็ได้รับการต้อนรับจากลูกค้าในร้านค้าและแกลเลอรีหลายแห่ง นายชูลทซ์ซื้อภาพวาดสีน้ำมันและของเก่าอันมีค่ามากมายในร้านขายของโบราณและหอศิลป์ แต่ชื่อเสียงของเขาในการเป็นซัพพลายเออร์ที่ดีนั้นยิ่งใหญ่กว่านั้นอีก คุณภาพของภาพวาดและสินค้าที่เขาเสนอขายนั้นโดดเด่นมาก หนังสือพิมพ์วันหนึ่งรายงานว่าแวร์เนอร์ ชูลทซ์พ่อค้างานศิลปะชื่อดังและนักแสดงเสียชีวิตแล้ว ไม่มีใครรู้ว่าเขาเสียชีวิตแล้วเนื่องจากนายชูลท์ซไม่มีญาติ นักข่าวจึงมองหาเพื่อนและญาติ"
