        "en": "Most scholars still agree that the \"African origin\" model holds that all or nearly all modern human genetic diversity around the world can be traced back to the first anatomically modern humans to leave Africa. The first Homo sapiens came out of North-East Africa, approximately 70 thousand years ago, and for at least 40,000 of those years, they obtained almost all of their food sources by hunting and gathering. This species then migrated out of Africa along a coastal route via the Arabian Peninsula to South- and Southeast Asia, and eventually reached the Pacific and Australia. About 50 thousand years ago, the first modern humans, a subspecies of Homo sapiens, migrated from Africa to Asia Minor, and over the Caucasus to Europe; regarding the history of Modern humans reached Central Europe about 40 thousand years ago. Humans also migrated to the Americas about 15 thousand years ago; most came over the land-bridge which is now called the Bering Strait. The 10th millennium BC saw the invention of agriculture and the beginning of the ancient era. The Neolithic Age or New Stone Age was a period in the development of human technology, which included primitive tools beginning about 10,200 BC. Hunter-gatherers of that time had access to goods and tools that",
